inline ::flatbuffers::Offset<ODRAttestation> CreateODRAttestation(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> SIGNING_PUBLIC_KEY = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SIGNED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> SIGNATURE = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> CANONICAL_JSON_SIGNATURE = 0) {
  ODRAttestationBuilder builder_(_fbb);
  builder_.add_CANONICAL_JSON_SIGNATURE(CANONICAL_JSON_SIGNATURE);
  builder_.add_SIGNATURE(SIGNATURE);
  builder_.add_SIGNED_AT(SIGNED_AT);
  builder_.add_SIGNING_PUBLIC_KEY(SIGNING_PUBLIC_KEY);
  return builder_.Finish();
}

