inline const ODR *GetODR(const void *buf) {
  return ::flatbuffers::GetRoot<ODR>(buf);
}

inline const ODR *GetSizePrefixedODR(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<ODR>(buf);
}

inline const char *ODRIdentifier() {
  return "$ODR";
}

inline bool ODRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ODRIdentifier());
}

inline bool SizePrefixedODRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ODRIdentifier(), true);
}

template <bool B = false>
inline bool VerifyODRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<ODR>(ODRIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedODRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<ODR>(ODRIdentifier());
}

inline void FinishODRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<ODR> root) {
  fbb.Finish(root, ODRIdentifier());
}

inline void FinishSizePrefixedODRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<ODR> root) {
  fbb.FinishSizePrefixed(root, ODRIdentifier());
}

inline std::unique_ptr<ODRT> UnPackODR(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<ODRT>(GetODR(buf)->UnPack(res));
}

inline std::unique_ptr<ODRT> UnPackSizePrefixedODR(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<ODRT>(GetSizePrefixedODR(buf)->UnPack(res));
}

